                    emailError.style.display = 'block';
                    return;
                }

                if (!terms.checked) {
                    alert('Please accept the terms and conditions.');
                    return;
                }

                // Show success toast
                const toast = document.createElement('div');
                toast.className = 'toast';
                toast.textContent = 'Reservation confirmed! Check your email.';
                document.body.appendChild(toast);
                toast.classList.add('show');

                setTimeout(() => {
                    toast.classList.remove('show');
                    setTimeout(() => {
                        document.body.removeChild(toast);
                    }, 300);
                }, 3000);

                ticketModal.style.display = 'none';
                ticketForm.reset();
                terms.checked = false;
            });

            ticketCount.addEventListener('change', function() {
                const tier = selectedTier.value;
                let price;

                if (tier === 'Night Pass') price = 29;
                else if (tier === 'Curator Pass') price = 59;
                else if (tier === 'Patron Pass') price = 129;

                totalPrice.value = '€' + (price * this.value);
            });

            // Email Validation for Newsletter
            const newsletterForm = document.getElementById('newsletterForm');
            const newsletterEmail = document.getElementById('newsletterEmail');
            const newsletterError = document.getElementById('newsletterError');

            newsletterForm.addEventListener('submit', function(e) {
                e.preventDefault();

                const emailValue = newsletterEmail.value;
                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

                if (!emailRegex.test(emailValue)) {
                    newsletterError.style.display = 'block';
                    return;
                }

                // Show success toast
                const toast = document.createElement('div');
                toast.className = 'toast';
                toast.textContent = 'Thank you for subscribing!';
                document.body.appendChild(toast);
                toast.classList.add('show');

                setTimeout(() => {
                    toast.classList.remove('show');
                    setTimeout(() => {
                        document.body.removeChild(toast);
                    }, 300);
                }, 3000);

                newsletterForm.reset();
            });

            // Save to Calendar
            const saveCalendarBtn = document.getElementById('saveCalendarBtn');

            saveCalendarBtn.addEventListener('click', function() {
                const icsContent = `BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//ARTIFACT Museum Night//EN\nCALSCALE:GREGORIAN\nBEGIN:VEVENT\nDTSTART:20261018T190000\nDTEND:20261019T020000\nSUMMARY:ARTIFACT: Museum Night\nDESCRIPTION:A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.\nLOCATION:The Old Gallery, Warsaw\nEND:VEVENT\nEND:VCALENDAR`;

                const blob = new Blob([icsContent], { type: 'text/calendar' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'artifact-museum-night.ics';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);

                // Show toast
                const toast = document.createElement('div');
                toast.className = 'toast';
                toast.textContent = 'Calendar file downloaded!';
                document.body.appendChild(toast);
                toast.classList.add('show');

                setTimeout(() => {
